# Example 1: Scan result
signals = 18
if signals >= 15:
    print("⚔️ Life forms detected!")
else:
    print("💨 Sector empty.")

# Example 2: System check
pressure_ok = False
if pressure_ok:
    print("🍺 Pressure chambers operational.")
else:
    print("🚫 Pressure drop detected!")

# Example 3: Energy check
energy = 45
consumption = 50
if energy >= consumption:
    print(f"💰 Jump possible! Remaining: {energy - consumption}%")
else:
    print(f"❌ Jump impossible! Missing: {consumption - energy}%")

# Example 1: Rank rating
points = 750
if points >= 1000:
    print("🏆 Fleet Commander!")
elif points >= 500:
    print("⭐ Captain!")
elif points >= 100:
    print("🌟 Lieutenant!")
else:
    print("📚 Cadet!")

# Example 2: Weapon system
weapon = "Laser"
if weapon == "Laser":
    print("🔥 Laser activated!")
elif weapon == "Plasma":
    print("💧 Plasma cannon loaded!")
elif weapon == "Quantum":
    print("🌪️ Quantum torpedo ready!")
elif weapon == "Ion":
    print("⚡ Ion cannon online!")
else:
    print("❓ Unknown weapon!")

# Example: The locked airlock
airlock_locked = True
right_code = True

if airlock_locked:
    print("🚪 The airlock is locked.")
    if right_code:
        print("🔑 The code is correct – the airlock opens!")
    else:
        print("❌ Wrong code! Access denied.")
else:
    print("🚪 The airlock is already open.")

status = 25
if status >= 18:
    print("System active")
elif:
    print("System inactive")
